import type { Post } from '@/payload-types'

export type EditorialLaunchArticle = {
  id: string
  slug: string
  primaryCategory: 'technology' | 'business' | 'information-systems' | 'africa'
  categories: string[]
  kind: 'analysis'
  readingTime: number
  featured: boolean
  editorsPick: boolean
  fr: {
    title: string
    excerpt: string
    metaTitle: string
    metaDescription: string
    content: string
  }
  en: {
    title: string
    excerpt: string
    metaTitle: string
    metaDescription: string
    content: string
  }
  sources: Array<{
    title: string
    publisher?: string
    url: string
    publishedAt?: string
    accessedAt: string
    language: 'fr' | 'en' | 'other'
    notes?: string
  }>
}

function textNode(text: string) {
  return {
    detail: 0,
    format: 0,
    mode: 'normal',
    style: '',
    text,
    type: 'text',
    version: 1,
  }
}

export function createEditorialLexicalDocument(source: string): Post['content'] {
  const blocks = source
    .trim()
    .split(/\n\s*\n/g)
    .map((block) => block.replace(/\s*\n\s*/g, ' ').trim())
    .filter(Boolean)

  const children = blocks.map((block) => {
    const heading = block.match(/^(#{2,4})\s+(.+)$/)

    if (heading) {
      return {
        children: [textNode(heading[2])],
        direction: 'ltr',
        format: '',
        indent: 0,
        tag: 'h' + heading[1].length,
        type: 'heading',
        version: 1,
      }
    }

    return {
      children: [textNode(block)],
      direction: 'ltr',
      format: '',
      indent: 0,
      textFormat: 0,
      type: 'paragraph',
      version: 1,
    }
  })

  return {
    root: {
      children,
      direction: 'ltr',
      format: '',
      indent: 0,
      type: 'root',
      version: 1,
    },
  } as unknown as Post['content']
}

